#!/usr/bin/env bash
# gifygrub::generate_theme WORKDIR THEME_NAME
#
# Writes a static theme.txt into WORKDIR alongside background.png.

gifygrub::generate_theme() {
    local workdir="$1"
    local theme_name="$2"

    cat > "${workdir}/theme.txt" <<EOF
# Auto-generated by gifygrub v${VERSION:-0.2.0}
# Theme: ${theme_name}
#
# NOTE: This is a static theme. GRUB2 has no native support for cycling
# through image frames as an animation.

title-text: ""
desktop-image: "background.png"
EOF

    echo "    wrote ${workdir}/theme.txt"
}
